Table "AREA_CODE_STATE" {
  "area_code" INTEGER [pk, not null]
  "state" TEXT [not null]
}

Table "CONTESTANTS" {
  "contestant_number" INTEGER [pk]
  "contestant_name" TEXT [not null]
}

Table "VOTES" {
  "vote_id" INTEGER [pk, not null]
  "phone_number" INTEGER [not null]
  "state" TEXT [not null]
  "contestant_number" INTEGER [not null]
  "created" TEXT [not null]
}



Ref: "VOTES"."contestant_number" > "CONTESTANTS"."contestant_number"

Ref: "VOTES"."state" > "AREA_CODE_STATE"."state"
